ALTER TABLE "contract_versions" ADD CONSTRAINT "contract_versions_template_binding_check" CHECK ("contract_versions"."template_version" = 1 AND (("contract_versions"."template_code" IN ('CONTRACT_ILLUSTRATIVE','CONTRACT_PREPARATION_ILLUSTRATIVE') AND "contract_versions"."clause_versions" = '[{"code":"CL_SUBJECT","version":1},{"code":"CL_PRICE","version":1},{"code":"CL_TERM","version":1},{"code":"CL_CONDITIONS","version":1},{"code":"CL_GENERAL","version":1}]'::jsonb AND "contract_versions"."pricing_snapshot_id" IS NOT NULL AND "contract_versions"."change_summary" IS NULL AND "contract_versions"."preliminary_work_scope" IS NULL AND "contract_versions"."preliminary_financial_conditions" IS NULL AND "contract_versions"."preliminary_limits" IS NULL) OR ("contract_versions"."template_code" = 'PRECONTRACT_ILLUSTRATIVE' AND "contract_versions"."clause_versions" = '[{"code":"CL_SUBJECT","version":1},{"code":"CL_PRICE","version":1},{"code":"CL_TERM","version":1},{"code":"CL_CONDITIONS","version":1},{"code":"CL_PRELIMINARY_WORK","version":1},{"code":"CL_GENERAL","version":1}]'::jsonb AND "contract_versions"."pricing_snapshot_id" IS NOT NULL AND "contract_versions"."change_summary" IS NULL AND "contract_versions"."term_ends_on" IS NOT NULL AND char_length("contract_versions"."preliminary_work_scope") BETWEEN 1 AND 2000 AND btrim("contract_versions"."preliminary_work_scope") <> '' AND char_length("contract_versions"."preliminary_financial_conditions") BETWEEN 1 AND 2000 AND btrim("contract_versions"."preliminary_financial_conditions") <> '' AND char_length("contract_versions"."preliminary_limits") BETWEEN 1 AND 2000 AND btrim("contract_versions"."preliminary_limits") <> '') OR ("contract_versions"."template_code" = 'ADDENDUM_ILLUSTRATIVE' AND "contract_versions"."clause_versions" = '[{"code":"CL_SUBJECT","version":1},{"code":"CL_PRICE","version":1},{"code":"CL_TERM","version":1},{"code":"CL_CONDITIONS","version":1},{"code":"CL_CHANGE","version":1},{"code":"CL_GENERAL","version":1}]'::jsonb AND char_length("contract_versions"."change_summary") BETWEEN 1 AND 4000 AND btrim("contract_versions"."change_summary") <> '' AND "contract_versions"."scope_note" IS NULL AND "contract_versions"."commercial_conditions" IS NULL AND "contract_versions"."special_conditions" IS NULL AND "contract_versions"."term_starts_on" IS NULL AND "contract_versions"."preliminary_work_scope" IS NULL AND "contract_versions"."preliminary_financial_conditions" IS NULL AND "contract_versions"."preliminary_limits" IS NULL)) IS TRUE);--> statement-breakpoint
ALTER TABLE "contracts" ADD CONSTRAINT "contracts_initial_check" CHECK (("contracts"."revision" > 0 AND "contracts"."illustrative_reference" > 0 AND (("contracts"."kind" IN ('CONTRACT','PRECONTRACT') AND ((("contracts"."origin" = 'ACCEPTED_OFFER' OR ("contracts"."kind" = 'CONTRACT' AND "contracts"."origin" = 'OFFER_PREPARATION')) AND "contracts"."source_offer_id" IS NOT NULL AND "contracts"."source_offer_version_id" IS NOT NULL AND "contracts"."direct_reason" IS NULL) OR ("contracts"."kind" = 'CONTRACT' AND "contracts"."origin" = 'DIRECT' AND "contracts"."source_offer_id" IS NULL AND "contracts"."source_offer_version_id" IS NULL AND char_length("contracts"."direct_reason") BETWEEN 1 AND 500 AND btrim("contracts"."direct_reason") <> '')) AND "contracts"."parent_contract_id" IS NULL AND "contracts"."addendum_ordinal" IS NULL AND ("contracts"."precontract_id" IS NULL OR ("contracts"."kind" = 'CONTRACT' AND "contracts"."precontract_id" <> "contracts"."id"))) OR ("contracts"."kind" = 'ADDENDUM' AND "contracts"."direct_reason" IS NULL AND "contracts"."origin" IS NULL AND "contracts"."source_offer_id" IS NULL AND "contracts"."source_offer_version_id" IS NULL AND "contracts"."parent_contract_id" IS NOT NULL AND "contracts"."parent_contract_id" <> "contracts"."id" AND "contracts"."addendum_ordinal" > 0 AND "contracts"."precontract_id" IS NULL))) IS TRUE);
