CREATE OR REPLACE FUNCTION guard_c6_version_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c contracts%ROWTYPE; p contract_versions%ROWTYPE;
BEGIN
 SELECT * INTO c FROM contracts WHERE workspace_id=NEW.workspace_id AND company_id=NEW.company_id AND id=NEW.contract_id FOR UPDATE;
 SELECT * INTO p FROM contract_versions WHERE workspace_id=c.workspace_id AND company_id=c.company_id AND contract_id=c.id ORDER BY version_number DESC LIMIT 1;
 IF (c.kind='CONTRACT' AND (NEW.template_code IS DISTINCT FROM CASE WHEN c.origin='OFFER_PREPARATION' THEN 'CONTRACT_PREPARATION_ILLUSTRATIVE' ELSE 'CONTRACT_ILLUSTRATIVE' END OR NEW.change_summary IS NOT NULL OR NEW.pricing_snapshot_id IS NULL)) OR (c.kind='PRECONTRACT' AND (NEW.template_code<>'PRECONTRACT_ILLUSTRATIVE' OR c.origin IS DISTINCT FROM 'ACCEPTED_OFFER')) OR (c.kind='ADDENDUM' AND NEW.template_code<>'ADDENDUM_ILLUSTRATIVE') THEN RAISE EXCEPTION 'Contract kind generation mismatch' USING ERRCODE='23514'; END IF;
 IF c.origin='OFFER_PREPARATION' THEN
  IF NOT EXISTS(SELECT 1 FROM offer_versions ov WHERE ov.workspace_id=c.workspace_id AND ov.company_id=c.company_id AND ov.offer_id=c.source_offer_id AND ov.opportunity_id=c.opportunity_id AND ov.original_client_account_id=c.original_client_account_id AND ov.id=NEW.source_offer_version_id AND ov.superseded_by_version_id IS NULL AND ov.provenance='ILLUSTRATIVE' AND ov.pricing_snapshot_id=NEW.pricing_snapshot_id AND ov.scope_note IS NOT DISTINCT FROM NEW.scope_note AND ov.commercial_conditions IS NOT DISTINCT FROM NEW.commercial_conditions AND ov.recipient_legal_name=NEW.recipient_legal_name AND ov.recipient_tax_id IS NOT DISTINCT FROM NEW.recipient_tax_id AND ov.recipient_legal_address IS NOT DISTINCT FROM NEW.recipient_legal_address AND ov.recipient_kind=NEW.recipient_kind AND ov.recipient_additional_legal_entity_id IS NOT DISTINCT FROM NEW.recipient_additional_legal_entity_id AND ((p.id IS NOT NULL AND EXISTS(SELECT 1 FROM offer_client_responses r WHERE r.workspace_id=ov.workspace_id AND r.company_id=ov.company_id AND r.offer_version_id=ov.id AND r.outcome='ACCEPTED')) OR (NOT EXISTS(SELECT 1 FROM offer_client_responses r WHERE r.workspace_id=ov.workspace_id AND r.company_id=ov.company_id AND r.offer_version_id=ov.id) AND ov.valid_until>NEW.created_at AND EXISTS(SELECT 1 FROM offer_decisions d WHERE d.workspace_id=ov.workspace_id AND d.company_id=ov.company_id AND d.offer_version_id=ov.id AND d.state='APPROVED') AND EXISTS(SELECT 1 FROM offer_transmissions t WHERE t.workspace_id=ov.workspace_id AND t.company_id=ov.company_id AND t.offer_version_id=ov.id) AND EXISTS(SELECT 1 FROM opportunities o WHERE o.workspace_id=c.workspace_id AND o.company_id=c.company_id AND o.id=c.opportunity_id AND o.status='OPEN')))) OR (p.id IS NULL AND NEW.source_offer_version_id IS DISTINCT FROM c.source_offer_version_id) THEN RAISE EXCEPTION 'Invalid Contract preparation source' USING ERRCODE='23514'; END IF;
 ELSIF NEW.source_offer_version_id IS NOT NULL THEN RAISE EXCEPTION 'Unexpected version source' USING ERRCODE='23514'; END IF;

 IF c.kind='ADDENDUM' AND NOT EXISTS(SELECT 1 FROM contracts pc JOIN contract_versions pv ON pv.contract_id=pc.id WHERE pc.workspace_id=c.workspace_id AND pc.company_id=c.company_id AND pc.id=c.parent_contract_id AND pc.kind IN ('CONTRACT','PRECONTRACT') AND pv.execution_state='EXECUTED' AND pv.recipient_kind=NEW.recipient_kind AND pv.recipient_additional_legal_entity_id IS NOT DISTINCT FROM NEW.recipient_additional_legal_entity_id) THEN RAISE EXCEPTION 'Invalid Addendum party' USING ERRCODE='23514'; END IF;
 IF c.origin='DIRECT' AND (char_length(NEW.scope_note) BETWEEN 1 AND 2000 AND btrim(NEW.scope_note)<>'' AND (NEW.commercial_conditions IS NULL OR char_length(NEW.commercial_conditions)<=4000)) IS NOT TRUE THEN RAISE EXCEPTION 'Invalid direct Contract content' USING ERRCODE='23514'; END IF;
 IF NEW.decision_state<>'PENDING' OR NEW.execution_state<>'NOT_EXECUTED' OR NEW.superseded_by_version_id IS NOT NULL OR NEW.superseded_at IS NOT NULL THEN RAISE EXCEPTION 'Invalid new Contract Version' USING ERRCODE='23514'; END IF;
 IF p.id IS NULL THEN
  IF NEW.version_number<>1 OR NEW.created_contract_revision<>1 OR NEW.predecessor_version_id IS NOT NULL OR c.revision<>1 THEN RAISE EXCEPTION 'Invalid initial Contract Version' USING ERRCODE='23514'; END IF;
 ELSE
  IF NEW.version_number<>p.version_number+1 OR NEW.predecessor_version_id IS DISTINCT FROM p.id OR NEW.created_contract_revision<>c.revision+1 OR p.superseded_by_version_id IS NOT NULL OR EXISTS(SELECT 1 FROM contract_versions WHERE contract_id=c.id AND execution_state='EXECUTED') OR (c.origin='ACCEPTED_OFFER' AND NEW.pricing_snapshot_id IS DISTINCT FROM p.pricing_snapshot_id) OR NEW.recipient_kind<>p.recipient_kind OR NEW.recipient_additional_legal_entity_id IS DISTINCT FROM p.recipient_additional_legal_entity_id OR (c.origin='ACCEPTED_OFFER' AND (NEW.scope_note IS DISTINCT FROM p.scope_note OR NEW.commercial_conditions IS DISTINCT FROM p.commercial_conditions)) OR NEW.issuing_company_label<>p.issuing_company_label THEN RAISE EXCEPTION 'Invalid Contract successor' USING ERRCODE='23514'; END IF;
 END IF;
 RETURN NEW;
END; $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION guard_c6_version_chain() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c contracts%ROWTYPE; v contract_versions%ROWTYPE; s contract_signatures%ROWTYPE; links integer;
BEGIN
 IF TG_TABLE_NAME='contracts' THEN SELECT * INTO c FROM contracts WHERE id=NEW.id;
 ELSE SELECT * INTO c FROM contracts WHERE id=NEW.contract_id; END IF;
 SELECT * INTO v FROM contract_versions WHERE workspace_id=c.workspace_id AND company_id=c.company_id AND contract_id=c.id ORDER BY version_number DESC LIMIT 1;
 SELECT * INTO s FROM contract_signatures WHERE contract_version_id=v.id;
 SELECT count(*) INTO links FROM contract_project_links WHERE workspace_id=c.workspace_id AND company_id=c.company_id AND contract_id=c.id;
 IF v.id IS NULL OR c.revision <> v.created_contract_revision + (CASE WHEN v.decision_state='PENDING' THEN 0 ELSE 1 END) + (CASE WHEN v.execution_state='EXECUTED' THEN 1 ELSE 0 END) + links OR v.superseded_by_version_id IS NOT NULL OR v.version_number<>(SELECT count(*) FROM contract_versions WHERE contract_id=c.id) THEN RAISE EXCEPTION 'Invalid Contract head revision' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM contract_versions p LEFT JOIN contract_versions n ON n.predecessor_version_id=p.id WHERE p.contract_id=c.id AND ((p.id<>v.id AND (n.id IS NULL OR p.superseded_by_version_id IS DISTINCT FROM n.id OR p.superseded_at IS DISTINCT FROM n.created_at OR n.version_number<>p.version_number+1 OR n.created_contract_revision<>p.created_contract_revision+CASE WHEN p.decision_state='PENDING' THEN 1 ELSE 2 END)) OR (p.id=v.id AND (n.id IS NOT NULL OR p.superseded_by_version_id IS NOT NULL)))) THEN RAISE EXCEPTION 'Invalid Contract lineage' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM contract_versions n WHERE n.contract_id=c.id AND n.version_number>1 AND (NOT EXISTS(SELECT 1 FROM contract_commands r WHERE r.workspace_id=n.workspace_id AND r.company_id=n.company_id AND r.result_contract_id=n.contract_id AND r.result_version_id=n.id AND r.kind='CREATE_VERSION' AND r.opportunity_id=c.opportunity_id AND r.actor_workspace_membership_id=n.created_by_workspace_membership_id AND r.created_at=n.created_at) OR NOT EXISTS(SELECT 1 FROM contract_events e WHERE e.workspace_id=n.workspace_id AND e.company_id=n.company_id AND e.contract_id=n.contract_id AND e.contract_version_id=n.id AND e.action='contract_version.created' AND e.actor_workspace_membership_id=n.created_by_workspace_membership_id AND e.actor_internal_user_id=n.created_by_internal_user_id AND e.occurred_at=n.created_at AND e.metadata=(jsonb_build_object('contractId',c.id::text,'contractVersionId',n.id::text,'versionNumber',n.version_number,'predecessorVersionNumber',n.version_number-1,'kind',c.kind,'provenance','ILLUSTRATIVE') || CASE WHEN c.kind='ADDENDUM' THEN jsonb_build_object('parentContractId',c.parent_contract_id::text,'addendumOrdinal',c.addendum_ordinal) WHEN c.origin='DIRECT' THEN jsonb_build_object('origin','DIRECT') ELSE jsonb_build_object('origin',c.origin,'offerVersionId',CASE WHEN c.origin='OFFER_PREPARATION' THEN n.source_offer_version_id::text ELSE c.source_offer_version_id::text END) END || CASE WHEN n.pricing_snapshot_id IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('pricingSnapshotId',n.pricing_snapshot_id::text) END)))) THEN RAISE EXCEPTION 'Incomplete Contract version evidence' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION guard_c8_event_source() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c contracts%ROWTYPE; v contract_versions%ROWTYPE;
BEGIN
 SELECT * INTO c FROM contracts WHERE workspace_id=NEW.workspace_id AND company_id=NEW.company_id AND id=NEW.contract_id;
 IF NEW.action='contract_project.linked' THEN RETURN NEW; END IF;
 IF NEW.metadata->>'kind' IS DISTINCT FROM c.kind THEN RAISE EXCEPTION 'Invalid Contract event kind' USING ERRCODE='23514'; END IF;
 IF c.kind IN ('CONTRACT','PRECONTRACT') AND (NEW.metadata->>'origin' IS DISTINCT FROM c.origin OR (c.origin='DIRECT' AND NEW.metadata ? 'offerVersionId') OR (c.origin='ACCEPTED_OFFER' AND NEW.metadata->>'offerVersionId' IS DISTINCT FROM c.source_offer_version_id::text)) THEN RAISE EXCEPTION 'Invalid Contract event source' USING ERRCODE='23514'; END IF;
 IF c.kind='ADDENDUM' AND (NEW.metadata->>'parentContractId' IS DISTINCT FROM c.parent_contract_id::text OR NEW.metadata->>'addendumOrdinal' IS DISTINCT FROM c.addendum_ordinal::text) THEN RAISE EXCEPTION 'Invalid Addendum event source' USING ERRCODE='23514'; END IF;
 IF NEW.contract_version_id IS NOT NULL THEN
  SELECT * INTO v FROM contract_versions WHERE id=NEW.contract_version_id AND contract_id=c.id;
  IF v.id IS NULL OR NEW.metadata->>'contractVersionId' IS DISTINCT FROM v.id::text OR NEW.metadata->>'versionNumber' IS DISTINCT FROM v.version_number::text OR (v.pricing_snapshot_id IS NULL AND NEW.metadata ? 'pricingSnapshotId') OR (v.pricing_snapshot_id IS NOT NULL AND NEW.metadata->>'pricingSnapshotId' IS DISTINCT FROM v.pricing_snapshot_id::text) THEN RAISE EXCEPTION 'Invalid Contract version event source' USING ERRCODE='23514'; END IF;
 END IF;
 IF c.origin='OFFER_PREPARATION' AND NEW.metadata->>'offerVersionId' IS DISTINCT FROM (CASE WHEN NEW.contract_version_id IS NULL THEN c.source_offer_version_id ELSE v.source_offer_version_id END)::text THEN RAISE EXCEPTION 'Invalid Contract preparation source event' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END; $$;
--> statement-breakpoint
CREATE OR REPLACE FUNCTION guard_contract_preparation_creation_evidence() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE c contracts%ROWTYPE; v contract_versions%ROWTYPE; source_metadata jsonb;
BEGIN
 SELECT * INTO c FROM contracts WHERE id=NEW.id;
 IF c.origin IS DISTINCT FROM 'OFFER_PREPARATION' THEN RETURN NULL; END IF;
 SELECT * INTO v FROM contract_versions WHERE contract_id=c.id AND version_number=1;
 source_metadata:=jsonb_build_object('contractId',c.id::text,'kind','CONTRACT','origin','OFFER_PREPARATION','offerVersionId',v.source_offer_version_id::text,'provenance','ILLUSTRATIVE','pricingSnapshotId',v.pricing_snapshot_id::text);
 IF v.id IS NULL OR NOT EXISTS(SELECT 1 FROM contract_commands r WHERE r.workspace_id=c.workspace_id AND r.company_id=c.company_id AND r.result_contract_id=c.id AND r.kind='CREATE' AND r.opportunity_id=c.opportunity_id AND r.actor_workspace_membership_id=c.created_by_workspace_membership_id AND r.created_at=c.created_at) OR NOT EXISTS(SELECT 1 FROM contract_events e WHERE e.workspace_id=c.workspace_id AND e.company_id=c.company_id AND e.contract_id=c.id AND e.action='contract.created' AND e.actor_internal_user_id=c.created_by_internal_user_id AND e.actor_workspace_membership_id=c.created_by_workspace_membership_id AND e.occurred_at=c.created_at AND e.metadata=(source_metadata-'pricingSnapshotId')||jsonb_build_object('illustrativeReference',c.illustrative_reference)) OR NOT EXISTS(SELECT 1 FROM contract_events e WHERE e.workspace_id=c.workspace_id AND e.company_id=c.company_id AND e.contract_id=c.id AND e.contract_version_id=v.id AND e.action='contract_version.created' AND e.actor_internal_user_id=v.created_by_internal_user_id AND e.actor_workspace_membership_id=v.created_by_workspace_membership_id AND e.occurred_at=v.created_at AND e.metadata=source_metadata||jsonb_build_object('contractVersionId',v.id::text,'versionNumber',1)) THEN RAISE EXCEPTION 'Incomplete preparation Contract creation evidence' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END; $$;
--> statement-breakpoint
CREATE CONSTRAINT TRIGGER contracts_preparation_evidence AFTER INSERT ON contracts DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION guard_contract_preparation_creation_evidence();
